import { expect, test, uniqueName } from "../../fixtures";

const DOCUMENTS = [
  { kind: "w9", text: "Legal Name: Harborline Logistics LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n" },
  { kind: "insurance_certificate", text: "Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: 2027-03-31\n" },
  { kind: "contract", text: "Counterparty: Harborline Logistics LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n" },
];

test("rejecting an extraction requires a note and returns the vendor to the member", { tag: "@REV-06" }, async ({ apiAs }) => {
  // Arrange: a vendor in review with three extractions
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Harborline Rev"), category: "logistics", contact_email: "ops@harborline.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  for (const doc of DOCUMENTS) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: { kind: doc.kind, file: { name: `${doc.kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(doc.text) } },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  await expect
    .poll(
      async () => {
        const list = (await (await member.get(`/api/vendors/${vendor.id}/documents`)).json()) as { status: string }[];
        return list.length === 3 && list.every((d) => d.status === "extracted");
      },
      { timeout: 60_000 },
    )
    .toBe(true);

  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);

  const documents = (await (await member.get(`/api/vendors/${vendor.id}/documents`)).json()) as { id: string; kind: string }[];
  const w9Document = documents.find((d) => d.kind === "w9");
  expect(w9Document, "W-9 document is present").toBeTruthy();
  const extraction = await member.get(`/api/documents/${w9Document!.id}/extraction`);
  expect(extraction.status(), await extraction.text()).toBe(200);
  const w9Extraction = await extraction.json();
  expect(w9Extraction.status).toBe("pending_review");

  // Act: reject without a note
  const withoutNote = await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
    data: { decision: "reject" },
  });

  // Assert: refused
  expect(withoutNote.status(), await withoutNote.text()).toBe(422);

  // Act: reject with a note
  const withNote = await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });
  expect(withNote.status(), await withNote.text()).toBe(200);

  // Assert: vendor returned to the member and the audit event recorded
  const vendorRes = await member.get(`/api/vendors/${vendor.id}`);
  expect(vendorRes.status(), await vendorRes.text()).toBe(200);
  expect((await vendorRes.json()).status, await vendorRes.text()).toBe("rejected");

  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const actions = ((await auditRes.json()).items as { action: string }[]).map((e) => e.action);
  expect(actions, await auditRes.text()).toContain("extraction.rejected");
});
